def is_copy_only_path(path, context):
    """Check whether the given `path` should only be copied and not rendered.

    This function checks if a file or directory path specified by `path` matches any pattern in the `context['cookiecutter']['_copy_without_render']` list. If a match is found, it returns True indicating that the path should only be copied and not rendered. Otherwise, it returns False.

    Parameters:
        path (str): A file-system path referring to a file or directory that should be rendered or just copied.
        context (dict): The cookiecutter context dictionary containing configuration settings.

    Returns:
        bool: True if the `path` matches any pattern in the `context['cookiecutter']['_copy_without_render']` list, otherwise False.

    Example:
        ```python
        # Assuming 'context' contains the appropriate keys and values
        context = {
            'cookiecutter': {
                '_copy_without_render': ['*.txt', '*.md']
            }
        }

        print(is_copy_only_path('file.txt', context))  # Output: True
        print(is_copy_only_path('directory/file.txt', context))  # Output: False
        ```
    """
    try:
        for dont_render in context['cookiecutter']['_copy_without_render']:
            if fnmatch.fnmatch(path, dont_render):
                return True
    except KeyError:
        return False

    return False
